constexpr size_t MAX_JSON=1048576,MAX_LINE=1398200;
struct Error:std::runtime_error{std::string code;Error(std::string c,std::string m):runtime_error(m),code(std::move(c)){} };
inline void require(bool b,const std::string&m){if(!b)throw Error("BAD_PAYLOAD",m);}
inline bool utf8(const std::string&s){for(size_t i=0;i<s.size();){unsigned char c=(unsigned char)s[i++];if(c<128)continue;int n;uint32_t v,min;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;min=128;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;min=2048;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;min=65536;}else return false;while(n--){if(i>=s.size())return false;unsigned char t=(unsigned char)s[i++];if((t&192)!=128)return false;v=(v<<6)|(t&63);}if(v<min||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
inline void append_utf8(std::string&s,uint32_t v){if(v<128)s+=char(v);else if(v<2048){s+=char(192|(v>>6));s+=char(128|(v&63));}else if(v<65536){s+=char(224|(v>>12));s+=char(128|((v>>6)&63));s+=char(128|(v&63));}else{s+=char(240|(v>>18));s+=char(128|((v>>12)&63));s+=char(128|((v>>6)&63));s+=char(128|(v&63));}}
struct J{enum Type{Null,Bool,Int,String,Array,Object}type=Null;int64_t number=0;std::string str;std::vector<J>arr;std::map<std::string,J>obj;
 const J&at(const std::string&k)const{require(type==Object&&obj.contains(k),"missing field "+k);return obj.at(k);}std::string text()const{require(type==String,"string expected");return str;}
 int64_t integer(int64_t lo,int64_t hi)const{require(type==Int&&number>=lo&&number<=hi,"integer range");return number;}
 void keys(std::initializer_list<const char*>ks)const{require(type==Object&&obj.size()==ks.size(),"unexpected fields");for(auto k:ks)require(obj.contains(k),"missing field");}
};
inline std::string quote(const std::string&s){std::string out="\"";const char*h="0123456789abcdef";for(unsigned char c:s){if(c=='"'||c=='\\'){out+='\\';out+=char(c);}else if(c<32){out+="\\u00";out+=h[c>>4];out+=h[c&15];}else out+=char(c);}return out+'"';}
inline std::string dump(const J&v){switch(v.type){case J::Null:return "null";case J::Bool:return v.number?"true":"false";case J::Int:return std::to_string(v.number);case J::String:return quote(v.str);case J::Array:{std::string s="[";for(auto&a:v.arr){if(s.size()>1)s+=',';s+=dump(a);}return s+']';}case J::Object:{std::string s="{";for(auto&[k,a]:v.obj){if(s.size()>1)s+=',';s+=quote(k)+':'+dump(a);}return s+'}';}}return "";}
class Parser{const std::string&s;size_t i=0;void ws(){while(i<s.size()&&(s[i]==' '||s[i]=='\r'||s[i]=='\n'||s[i]=='\t'))++i;}char get(){require(i<s.size(),"truncated JSON");return s[i++];}
 uint32_t hex(){uint32_t v=0;for(int n=0;n<4;++n){char c=get();int k=c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;require(k>=0,"unicode escape");v=v*16+uint32_t(k);}return v;}
 std::string string(){require(get()=='"',"string expected");std::string out;for(;;){unsigned char c=(unsigned char)get();if(c=='"')break;require(c>=32,"control in string");if(c!='\\')out+=char(c);else{char e=get();switch(e){case '"':case '\\':case '/':out+=e;break;case 'b':out+='\b';break;case 'f':out+='\f';break;case 'n':out+='\n';break;case 'r':out+='\r';break;case 't':out+='\t';break;case 'u':{auto v=hex();if(v>=0xd800&&v<=0xdbff){require(get()=='\\'&&get()=='u',"surrogate pair");auto w=hex();require(w>=0xdc00&&w<=0xdfff,"low surrogate");v=0x10000+((v-0xd800)<<10)+(w-0xdc00);}else require(v<0xdc00||v>0xdfff,"lone surrogate");append_utf8(out,v);break;}default:require(false,"string escape");}}require(out.size()<=8192,"string limit");}return out;}
 J value(int depth){require(depth<24,"nesting limit");ws();require(i<s.size(),"missing value");J v;char c=s[i];if(c=='"'){v.type=J::String;v.str=string();return v;}if(c=='{'||c=='['){++i;v.type=c=='{'?J::Object:J::Array;ws();char end=c=='{'?'}':']';if(i<s.size()&&s[i]==end){++i;return v;}for(;;){ws();if(c=='{'){auto k=string();ws();require(get()==':',"colon");require(!v.obj.contains(k),"duplicate key");v.obj.emplace(k,value(depth+1));}else v.arr.push_back(value(depth+1));ws();char next=get();if(next==end)break;require(next==',',"comma");}return v;}
  for(auto word:{"true","false","null"}){std::string w=word;if(s.compare(i,w.size(),w)==0){i+=w.size();v.type=w=="null"?J::Null:J::Bool;v.number=w=="true";return v;}}
  size_t start=i;if(c=='-')++i;require(i<s.size()&&s[i]>='0'&&s[i]<='9',"integer expected");if(s[i]=='0')++i;else while(i<s.size()&&s[i]>='0'&&s[i]<='9')++i;auto part=s.substr(start,i-start);auto[p,e]=std::from_chars(part.data(),part.data()+part.size(),v.number);require(e==std::errc()&&p==part.data()+part.size(),"integer overflow");v.type=J::Int;return v;}
 public:explicit Parser(const std::string&t):s(t){}J parse(){require(s.size()<=MAX_JSON&&utf8(s),"size/UTF8");auto v=value(0);ws();require(i==s.size(),"trailing JSON");return v;}};
inline const std::string alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
inline std::string b64(const std::string&s){std::string out;uint32_t a=0;int bits=0;for(unsigned char c:s){a=(a<<8)|c;bits+=8;while(bits>=6){bits-=6;out+=alphabet[(a>>bits)&63];}}if(bits)out+=alphabet[(a<<(6-bits))&63];return out;}
inline std::string unb64(const std::string&s){require(!s.empty()&&s.size()%4!=1&&s.size()<=1398102,"base64 length");std::string out;uint32_t a=0;int bits=0;for(char c:s){auto k=alphabet.find(c);require(k!=std::string::npos,"base64 alphabet/padding");a=(a<<6)|uint32_t(k);bits+=6;if(bits>=8){bits-=8;out+=char((a>>bits)&255);}}require((bits==0||(a&((1u<<bits)-1))==0)&&b64(out)==s,"base64 pad bits");return out;}
inline J decode(const std::string&s){return Parser(unb64(s)).parse();}
inline bool side(const std::string&s){return s=="CAM"||s=="XANH";}
inline bool type(const std::string&s){return std::set<std::string>{"VUONG","TUONG","SI","KI","XA","LONG","PHUONG","BINH"}.contains(s);}
inline bool rotates(const std::string&s){return s!="VUONG"&&s!="LONG"&&s!="PHUONG";}
inline void position(const J&p){p.keys({"board","to_move","reserve","prisoners"});require(side(p.at("to_move").text()),"side");auto&b=p.at("board");require(b.type==J::Array&&b.arr.size()==81,"board81");int total=0,cam=0,xanh=0;for(auto&st:b.arr){require(st.type==J::Array&&st.arr.size()<=38,"stack38");std::string own;for(auto&q:st.arr){q.keys({"type","owner","facing"});auto t=q.at("type").text(),o=q.at("owner").text();require(type(t)&&side(o),"piece type/owner");q.at("facing").integer(0,3);require(own.empty()||own==o,"mixed team");own=o;++total;if(t=="VUONG"){require(st.arr.size()==1,"king in team");if(o=="CAM")++cam;else ++xanh;}}}
 for(auto hand:{"reserve","prisoners"}){auto&h=p.at(hand);h.keys({"CAM","XANH"});for(auto pl:{"CAM","XANH"}){auto&a=h.at(pl);require(a.type==J::Array,"hand array");std::set<std::string>seen;for(auto&v:a.arr){auto t=v.text();require(type(t)&&t!="VUONG","hand type");if(std::string(hand)=="reserve")require((t=="LONG"||t=="PHUONG")&&seen.insert(t).second,"reserve unique LONG/PHUONG");++total;}}}require(cam==1&&xanh==1&&total<=40,"king/40 bound");}
inline std::string identity(J p){for(auto hand:{"reserve","prisoners"})for(auto pl:{"CAM","XANH"}){auto&a=p.obj[hand].obj[pl].arr;std::sort(a.begin(),a.end(),[](auto&x,auto&y){return x.str<y.str;});}return dump(p);}
inline void state(const J&s){s.keys({"schema","position","ply","repetition","result","notation"});require(s.at("schema").text()=="clp.state/1","state schema");position(s.at("position"));s.at("ply").integer(0,1000000);auto&r=s.at("repetition");r.keys({"complete","entries"});require(r.at("complete").type==J::Bool&&r.at("complete").number==1,"complete repetition");auto&a=r.at("entries");require(a.type==J::Array&&!a.arr.empty()&&a.arr.size()<=4096,"history entries");std::set<std::string>keys;int current=0;auto currentkey=identity(s.at("position"));for(auto&e:a.arr){e.keys({"position","count"});position(e.at("position"));auto k=identity(e.at("position"));require(keys.insert(k).second,"duplicate history");int n=int(e.at("count").integer(1,3));if(k==currentkey)current=n;}require(current>0,"current entry");auto&res=s.at("result");auto status=res.at("status").text();if(status=="ongoing"){res.keys({"status"});for(auto&e:a.arr)require(e.at("count").number<3,"ongoing repetition3");}else{require(status=="terminal","result status");res.keys({"status","reason","winner","loser"});auto reason=res.at("reason").text();require(std::set<std::string>{"checkmate","pat","repetition3","resign","max_plies"}.contains(reason),"terminal reason");if(reason=="max_plies")require(res.at("winner").type==J::Null&&res.at("loser").type==J::Null,"maxplies NONE");else{auto w=res.at("winner").text(),l=res.at("loser").text();require(side(w)&&side(l)&&w!=l,"winner loser");if(reason=="repetition3")require(current==3&&w==s.at("position").at("to_move").str,"repetition mover loses");}}auto&nt=s.at("notation");if(nt.type!=J::Null){nt.keys({"format","text","legacy_turnabout"});require(nt.at("format").text()=="LPGF"||nt.at("format").text()=="TXT","notation format");nt.at("text").text();require(nt.at("legacy_turnabout").type==J::Bool,"legacy flag");}}
inline void square(const J&v){require(v.type==J::Array&&v.arr.size()==2,"square");v.arr[0].integer(0,8);v.arr[1].integer(0,8);}
inline void move(const J&m){m.keys({"schema","kind","src","dst","ptype","facing","rotate_after","notation"});require(m.at("schema").text()=="clp.move/1","move schema");auto k=m.at("kind").text(),t=m.at("ptype").text();require(type(t),"move type");auto rot=m.at("rotate_after").integer(0,3);require(rot!=2,"180 live forbidden");if(m.at("notation").type!=J::Null)m.at("notation").text();if(k=="drop"){require(m.at("src").type==J::Null&&t!="VUONG"&&rot==0,"drop fields");square(m.at("dst"));m.at("facing").integer(0,3);}else{require(k=="rotate"||k=="single"||k=="team","move kind");square(m.at("src"));require(m.at("facing").type==J::Null,"board facing null");if(k=="rotate")require(m.at("dst").type==J::Null&&rot!=0&&rotates(t),"rotate fields");else{square(m.at("dst"));require(dump(m.at("src"))!=dump(m.at("dst")),"same square");require(rot==0||rotates(t),"fixed rotation");require(k!="team"||t!="VUONG","king team");}}}
inline void info(const J&v){v.keys({"schema","id","depth","nodes","time_ms","multipv","score","bound","pv"});require(v.at("schema").text()=="clp.info/1","info schema");v.at("id").integer(1,2147483647);v.at("depth").integer(0,1024);v.at("nodes").integer(0,9007199254740991LL);v.at("time_ms").integer(0,86400000);v.at("multipv").integer(1,256);auto b=v.at("bound").text();require(b=="exact"||b=="lower"||b=="upper","bound");auto&s=v.at("score");s.keys({"kind","value","perspective"});require(s.at("perspective").text()=="root","score perspective");auto k=s.at("kind").text();require(k=="cp"||k=="mate"||k=="value_milli","score kind");s.at("value").integer(k=="value_milli"?-1000:-1000000,k=="value_milli"?1000:1000000);auto&a=v.at("pv");require(a.type==J::Array&&a.arr.size()<=256,"PV256");for(auto&m:a.arr)move(m);}
inline int64_t integer(const std::string&s,int64_t lo,int64_t hi){int64_t v=0;auto[p,e]=std::from_chars(s.data(),s.data()+s.size(),v);if(e!=std::errc()||p!=s.data()+s.size()||v<lo||v>hi)throw Error("BAD_COMMAND","numeric token");return v;}
